function gapChart(models){return models.map(m=>{const train=Number(m.training_auc),valid=Number(m.metrics.roc_auc),gap=Math.max(0,train-valid);return `<div class="gap-row"><div><b>${esc(m.label)}</b><small>${esc(m.feature_set)}</small></div><div class="paired"><span style="width:${train*100}%">训练 ${train.toFixed(3)}</span><i style="width:${valid*100}%">验证 ${valid.toFixed(3)}</i></div><strong class="${gap>.08?'alert':''}">差距 ${gap.toFixed(3)}</strong></div>`}).join('')}
