const moduleHelp=[
[/^预测时点$/,'模型模拟患者入院、血常规结果已经产生的时点。此时只能使用入院时已经获得的资料，不能偷看住院后的检查或出院诊断。'],
[/^模型输入$/,'输入包括入院血常规、年龄、转换后的性别和入院诊断。姓名、身份证号、出院诊断和金标准标签均不进入模型。'],
[/^评价金标准$/,'金标准是患者最终出院诊断是否明确地中海贫血，只用于历史数据的训练与验证；真实入院预测时尚不可获得。'],
[/原始 CSV|原始资料/,'原始表用于确认字段、单位和数据形态。此时只观察，不提前修改或标记答案。'],
[/问题|命中量/,'命中数表示规则发现的记录数量，不等于真实错误数量；危急值仍需人工核验。'],
[/单位/,'同一指标必须先统一单位再比较。本课按1 g/dL=10 g/L把HGB统一成g/L。'],
[/年龄分布/,'分布图帮助发现负值、极端值和样本集中区间，但不能单靠图形判定记录真假。'],
[/性别/,'性别原始编码按数据字典统一为0/1；0和1只是类别代码，不代表大小关系。'],
[/缺失位置/,'缺失位置图用于判断缺失是否集中在某些记录区间；它不说明缺失机制一定是随机的。'],
[/证据记录/,'这里只展示被当前规则命中的代表记录，处理决定仍需结合单位、业务含义和患者安全。'],
[/处理方法|待处理/,'标准答案代表本课采用的规范处理。答错时系统解释风险，答对后才进入下一项。'],
[/完整病例删除/,'删除含缺失值的记录最简单，但会减少样本；若缺失与病情有关，还可能产生选择偏倚。'],
[/中位数填补/,'中位数受极端值影响较小，适合连续变量的简单填补；参数只能由训练折计算。'],
[/KNN 填补|KNN填补/,'KNN根据其他变量相近的训练患者估计缺失值。它能产生个体化填充值，但依赖量纲、邻居数和样本结构。'],
[/本章怎样比较/,'三种方法使用同一套患者级5折划分。每一折只在训练患者中拟合填补规则与逻辑回归，再对未参与拟合的验证患者计算预测概率和AUC。'],
[/AUC/,'ROC AUC衡量模型排序能力：随机取一名阳性和一名阴性，阳性风险排得更高的概率。0.5接近随机，1.0为完全排序正确。'],
[/HGB 分布/,'同时看填补前、填补值和填补后全体分布，判断填补是否制造尖峰、压缩变异或改变尾部。'],
[/填补前后摘要/,'分位数比均值更容易看出分布位置与范围变化。填补值摘要只统计原本缺失的记录。'],
[/常见的数据处理/,'处理方法由变量类型、分布、算法和研究目的决定；并非所有变量都需要转换。'],
[/右偏|log\(1\+x\)|经过 log/,'log(1+x)用于压缩长右尾和极高值。x≥0时可直接使用；是否保留应结合分布、线性关系和交叉验证结果。'],
[/非数值变量|诊断编码/,'二元类别可映射0/1；无等级的多类别或多标签变量通常展开为独热编码列。'],
[/标准化|Z标准化/,'Z标准化把训练折均值变为0、标准差变为1。逻辑回归、LASSO、KNN和PCA常需要；树模型通常不需要。'],
[/相关性/,'Pearson相关系数描述两个连续变量的线性关系。本课以|r|≥0.85提示高度重复，但相关不等于因果。'],
[/高相关变量/,'高度相关变量同时进入线性模型可能使系数不稳定。本课优先保留临床含义更直接的原始指标。'],
[/本章只做三件事|筛选流程/,'本章先处理高度相关变量，再用LASSO选择惩罚强度，最后形成一套候选特征。模型效果要到下一章用未参与筛选的验证患者评价。'],
[/LASSO系数路径/,'固定λ时，L1逻辑回归最小化“二项损失+λ×系数绝对值之和”。该目标是凸的；数据有限、完成标准化且求解器收敛到容差后，可得到该λ下的全局最优解。'],
[/交叉验证选择λ/,'λmin是在搜索网格中五折平均二项偏差最低的λ；λ1se是在最低误差+1个标准误以内选择最大的λ。前者偏重拟合，后者偏重简洁稳定。这里的“最优”只针对当前数据、指标和λ网格。'],
[/1-SE|入选特征/,'1-SE规则偏向更精简的模型，但不保证验证AUC更高。本课先比较λmin和λ1se的外层验证AUC；若λ1se损失超过0.01，就保留λmin，避免过度收缩。'],
[/最终进入LASSO模型的特征|最终进入模型比较的特征/,'这些变量组成最终LASSO逻辑回归。它会与使用全部变量的普通逻辑回归在同一批验证患者上比较，以判断筛选是否真正改善泛化。'],
[/未入选变量/,'系数被压到0表示该变量在当前数据、其他变量和λ下没有被LASSO保留，不代表它在医学上没有价值。'],
[/嵌套患者级交叉验证/,'外层5折只评价泛化；每个外层训练集内部再做5折选择λ。同一患者不能同时出现在训练侧和验证侧。'],
[/逻辑回归/,'逻辑回归建立特征与对数优势之间的线性关系，输出0到1的概率；连续变量通常需要合理转换与标准化。'],
[/决策树/,'决策树按阈值递归分组，规则直观但未剪枝时容易记住训练样本。'],
[/随机森林/,'随机森林综合多棵随机化决策树的概率，通常比单棵树稳定，但解释需要借助SHAP等方法。'],
[/支持向量机|RBF-SVM/,'RBF支持向量机可以学习非线性边界，但对标准化和参数C、gamma较敏感。本课只在每个外层训练折内部用4折交叉验证选参。'],
[/所有模型共用同一组患者划分|八种方案共同使用的实际五折划分|五种方案共同使用的实际五折划分/,'这里不属于某一个模型，而是所有方案共同使用的患者分组。只有让每种方案在完全相同的训练患者和验证患者上比较，AUC差异才不会被不同抽样干扰。'],
[/ROC 曲线/,'ROC曲线展示不同阈值下敏感度与1−特异度的权衡；曲线越靠左上，整体排序能力通常越好。'],
[/训练 AUC|过拟合|差距/,'训练成绩明显高于验证成绩提示过拟合。判断时还应结合折间波动、样本量和外部验证。'],
[/LASSO筛选是否真正改善泛化/,'筛选有意义不能只看变量数量。本页同时检查验证AUC是否提高、训练—验证差距是否缩小，以及不同折之间是否稳定。'],
[/混淆矩阵/,'混淆矩阵按选定阈值统计真阳性、假阳性、真阴性和假阴性，直接对应漏提示与过度提示。'],
[/全局重要性/,'平均绝对SHAP值表示模型总体依赖该特征的程度，只反映模型行为，不证明因果。'],
[/蜂群图/,'每个点是一名患者；横轴为SHAP贡献方向和大小，颜色代表该特征取值的高低。'],
[/瀑布图/,'瀑布图从基础风险出发，逐项叠加该患者的SHAP贡献，最终到达模型预测概率。'],
[/风险阈值/,'阈值决定何时发出提示。降低阈值通常提高敏感度、减少漏报，但会增加误报。'],
[/PCA/,'PCA把相关变量组合成互不相关的主成分，使高维数据可以二维观察；它保留的是方差，不保证保留诊断信息。'],
[/分析顺序/,'无监督探索先标准化数值尺度，再用PCA投影到二维观察，最后比较不同k的聚类质量。PCA和KMeans承担不同任务。'],
[/肘部曲线/,'惯性是每个患者到所属簇中心的平方距离总和。k越大惯性一定越小，通常寻找下降速度开始明显变缓的“肘部”。'],
[/轮廓系数/,'轮廓系数综合比较簇内距离与最近其他簇的距离，越接近1分组越清楚，接近0表示簇之间重叠。'],
[/簇数|KMeans/,'KMeans按距离把患者分组。轮廓系数越高，簇内越紧、簇间越分离；聚类编号本身不是疾病名称。'],
[/金标准/,'出院诊断只在聚类完成后揭示，用于事后比较；无监督算法运行时看不到标签。']
];
function helpFor(title){const hit=moduleHelp.find(([re])=>re.test(title));return hit?hit[1]:`${title}用于展示本步骤的证据或结果。先看数据来源和单位，再结合本章目的解释，不能只凭单个数值下结论。`}
function decorateModules(root){const heads=[...root.querySelectorAll('h3')];heads.forEach((h,i)=>{const old=[...h.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim()||h.textContent.trim();const title=old.replace(/^\d+(?:[.–—-]\d+)?[.、．]?\s*/,'').replace(/^第[一二三四五六七八九十]+步[:：]?\s*/,'');h.textContent='';h.classList.add('module-heading');const index=document.createElement('span');index.className='module-index';index.textContent=String(i+1).padStart(2,'0');const label=document.createElement('span');label.className='module-title';label.textContent=title;const help=helpFor(title),b=document.createElement('button');b.type='button';b.className='help-badge';b.textContent='?';b.setAttribute('aria-label',`解释：${title}`);b.setAttribute('data-tip',help);b.title=help;h.append(index,label,b)})}
function decorateChapter(root){
  root.classList.add('lesson-stage');
  root.dataset.chapter=String(page+1);
  document.documentElement.style.setProperty('--course-progress',`${(page+1)/names.length*100}%`);
  const guide=chapterGuides[page],title=root.querySelector('h1');
  if(guide&&title&&!root.querySelector('.chapter-guide')){
    const box=document.createElement('div');box.className='chapter-guide';
    box.innerHTML=`<div><small>承接上一章</small><b>${guide.from}</b></div><i>→</i><div class="focus"><small>本章任务</small><b>${guide.task}</b></div><i>→</i><div><small>本章产出</small><b>${guide.out}</b></div>`;
    title.insertAdjacentElement('afterend',box);
  }
  root.querySelectorAll('.card').forEach(x=>x.classList.add('lesson-card'));
  const actions=[...root.querySelectorAll('.button')];if(actions.length)actions.at(-1).classList.add('chapter-action');
}
function nav(){q('#nav').innerHTML=names.map((n,i)=>`<button data-i="${i}" ${i>open?'disabled':''} class="${i===page?'active':''} ${i<open?'done':''}">${i<open?'✓ ':''}${i+1} ${n}</button>`).join('');q('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{page=+b.dataset.i;render()})}
function go(n){open=Math.max(open,n);page=n;render()}
async function render(){nav();try{const f=[home,raw,scan,quiz,missing,features,selectV2,modelsV2,shap,clusterV2][page];await f(q('#stage'));decorateModules(q('#stage'));decorateChapter(q('#stage'));window.scrollTo({top:0,left:0,behavior:'instant'})}catch(e){q('#stage').innerHTML=`<div class="card warning">${esc(e.message)}</div>`}}
function home(el){el.innerHTML=`<section class="hero"><div><div class="eyebrow">01 · 检验科研究任务</div><h1>把一次入院血常规，变成一条可复核的提示线索</h1><p>利用既往住院记录，探索患者刚入院时能否提示地中海贫血可能性；模型只作提示，不替代诊断。</p><div class="flow"><span class="pill">400 名模拟患者</span><span class="pill">入院血常规</span><span class="pill">入院诊断</span></div><button class="button" onclick="go(1)">开始研究 →</button></div><div class="hero-art"><div class="blood">●</div><div class="report"><span>入院检验单</span><i></i><i></i><i></i><b>风险提示</b></div><div class="hero-note">不是替代诊断<br><strong>而是提示进一步核查</strong></div></div></section><div class="grid g3 task-strip"><div><h3>预测时点</h3><span>入院完成血常规后</span></div><div><h3>模型输入</h3><span>入院资料，不含住院后信息</span></div><div><h3>评价金标准</h3><span>最终出院诊断作金标准</span></div></div>`}
async function raw(el){const d=await api('/dataset/raw');const labels=Object.fromEntries(d.columns.map(x=>[x.key,x.label]));const rows=d.rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[labels[k]||k,v])));el.innerHTML=`<div class="eyebrow">02 · 查看原始资料</div><h1 class="title">先看原始记录，再决定能不能建模</h1><div class="data-intro"><span><b>${d.summary.rows}</b> 条记录</span><span><b>${d.summary.patients}</b> 名患者</span><span>来源：${d.summary.source}</span><span>原始文件只读</span></div><div class="card"><h3>原始 CSV 前 20 行</h3><p class="muted">此时不标出错误。左右滚动可查看全部字段；下一步由规则扫描数据质量。</p>${table(rows)}</div><button class="button" onclick="go(2)">运行数据质量扫描 →</button>`}
async function scan(el){if(!checked)checked=await api('/checks/run',{method:'POST'});el.innerHTML=`<div class="eyebrow">03 数据质量检查</div><h1 class="title">先发现问题，再讨论处理方法</h1><div class="grid g2"><div class="card"><h3>七类问题的命中量</h3>${bars(checked.issues.map(x=>({label:x.title,count:x.affected_count})),'label','count','orange')}</div><div class="card"><h3>HGB 单位构成</h3>${bars(checked.distributions.units)}<h3>性别原始写法</h3>${bars(checked.distributions.sex)}</div></div><div class="grid g2"><div class="card"><h3>年龄分布</h3>${bars(checked.distributions.ages.map(x=>({label:x.from+'–'+x.to,count:x.count})))}</div><div class="card"><h3>HGB 缺失位置</h3><div class="missing-strip">${Array.from({length:100},(_,i)=>`<i class="${checked.distributions.missing_positions.some(x=>Math.floor(x/4)===i)?'miss':''}"></i>`).join('')}</div><p class="muted">每个小格约代表4条记录；橙色表示该区间出现HGB缺失。具体填补方法将在第五步比较。</p></div></div><button class="button" onclick="go(3)">逐项判断怎么处理 →</button>`;open=Math.max(open,3);nav()}
function quiz(el){const item=checked.issues.find(x=>!session.answers.includes(x.id));if(!item){go(4);return}const labels={record_id:'记录号',patient_id:'患者编号',sex_raw:'性别原始值',age:'年龄',hgb_value:'HGB值',hgb_unit:'HGB单位',admission_diagnoses:'入院诊断',discharge_diagnosis:'出院诊断',name:'姓名',id_number:'模拟身份证号'};const evidence=item.sample_records.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[labels[k]||k,v])));el.innerHTML=`<div class="eyebrow">04 数据处理 · 第 ${session.answered+1}/7 项</div><h1 class="title">${item.title}</h1><div class="split"><div class="card"><h3>待处理问题</h3>${checked.issues.map((x,i)=>`<div class="issue ${x.id===item.id?'active':''} ${session.answers.includes(x.id)?'done':''}"><span>${i+1}. ${x.title}</span><b>${session.answers.includes(x.id)?'✓':x.affected_count}</b></div>`).join('')}</div><div class="card"><h3>证据记录</h3>${table(evidence)}<h3>选择合适的处理方法</h3><p class="muted">${item.cause} 影响：${item.risk}</p>${item.options.map(o=>`<button class="quiz-option" data-a="${o[0]}">${o[1]}</button>`).join('')}<div id="feedback"></div></div></div>`;el.querySelectorAll('.quiz-option').forEach(b=>b.onclick=async()=>{const r=await api('/decisions',{method:'POST',body:JSON.stringify({issue_id:item.id,action:b.dataset.a})});q('#feedback').innerHTML=`<div class="feedback ${r.is_correct?'good':'bad'}">${r.feedback}${r.hint?'<br>'+r.hint:''}</div>`;if(r.is_correct){session=await api('/session');setTimeout(()=>r.next_issue_id?render():go(4),500)}})}
async function start(path,box,done){const j=await api(path,{method:'POST'});const timer=setInterval(async()=>{const r=await api('/jobs/'+j.job_id);box.innerHTML=`<div class="progress"><i style="width:${r.progress}%"></i></div>${r.progress}%　${esc(r.message)}`;if(r.status==='completed'){clearInterval(timer);window[done]=r.result;if(done==='imputation')imputation=r.result;if(done==='selection')selection=r.result;if(done==='comparison')comparison=r.result;open=Math.max(open,page+1);render()}if(r.status==='failed'){clearInterval(timer);box.innerHTML=`<div class="feedback bad">${esc(r.error)}</div>`}},500)}
function missing(el){if(!imputation){el.innerHTML=`<div class="eyebrow">05 缺失值实验室</div><h1 class="title">同一份缺失数据，不同处理会带来什么差异？</h1><div class="grid g3"><div class="card"><h3>完整病例删除</h3><p class="muted">简单，但会损失患者，并可能改变入组人群。</p></div><div class="card"><h3>中位数填补</h3><p class="muted">常用、稳定，受极端值影响较小。</p></div><div class="card"><h3>KNN 填补</h3><p class="muted">根据相似患者估计缺失值，能利用多变量信息，但计算更复杂。</p></div></div><div class="card"><h3>本章怎样比较</h3><p>固定同一套患者级5折。每轮只用训练患者拟合填补器和逻辑回归，验证患者只接受转换并产生预测。</p><button id="run" class="button">运行三种方法</button><div id="job"></div></div>`;q('#run').onclick=()=>{q('#run').disabled=true;start('/imputation/start',q('#job'),'imputation')};return}const a=imputation.auc_explanation,foldRows=a.fold_rows.map(x=>({'折次':`第${x.fold}折`,'完整病例删除':Number(x.complete).toFixed(4),'中位数填补':Number(x.median).toFixed(4),'KNN填补':Number(x.knn).toFixed(4)}));el.innerHTML=`<div class="eyebrow">05 缺失值实验室</div><h1 class="title">模型成绩与填补前后分布一起看</h1><div class="card"><h3>患者级交叉验证 AUC</h3>${bars(imputation.methods.map(x=>({label:x.label,score:x.metrics.roc_auc})),'label','score','green')}<div class="auc-explain"><div><b>AUC怎么得到？</b><p>${a.definition}</p><p>${a.calculation}</p></div><div><b>为什么中位数与KNN看起来一样？</b><p>精确结果是 <strong>${Number(a.median_auc).toFixed(4)}</strong> 与 <strong>${Number(a.knn_auc).toFixed(4)}</strong>，差值 ${Number(a.auc_gap).toFixed(4)}。先前显示3位小数，所以都显示为0.871。</p><p>${a.why_close} 两种方法对缺失HGB填充值的平均绝对差为 ${a.filled_mean_absolute_difference} g/L。</p></div></div>${table(foldRows)}<p class="muted">各折AUC可以不同；页面顶部总AUC使用全部折外预测一次性计算，因此不要求等于五个折AUC的简单平均。</p></div><div class="card"><div class="grid g2"><div><h3>HGB 分布</h3><select id="method"><option value="obs">填补前：已观测HGB</option>${imputation.distributions.map(x=>`<option value="${x.method}">${x.label}</option>`).join('')}</select><div id="hist"></div></div><div><h3>填补前后摘要</h3><div id="summary"></div><p class="muted">${imputation.distribution_note}</p></div></div><p class="warning">推荐：<b>${imputation.recommended_label}</b>。${imputation.rule}</p><button class="button" onclick="go(5)">查看特征工程</button></div>`;const row=(label,x)=>({'数据范围':label,'数量':x.count,'最小值':x.min,'下四分位数':x.q1,'中位数':x.median,'上四分位数':x.q3,'最大值':x.max});const draw=()=>{const selected=q('#method').value,x=selected==='obs'?{histogram:imputation.observed_hgb_histogram}:imputation.distributions.find(a=>a.method===selected);q('#hist').innerHTML=bars(x.histogram.map(a=>({label:a.from+'–'+a.to,count:a.count})));const rows=[row('填补前：原始已观测值',imputation.observed_summary)];if(selected!=='obs'){rows.push(row('新增填补值',x.filled_summary));rows.push(row('填补后：全体数据',x.completed_summary))}q('#summary').innerHTML=table(rows)};q('#method').onchange=draw;draw()}
async function features(el){preview=preview||await api('/features/preview');const zrows=preview.standardization.z_scores.filter(x=>['hgb_gl','rbc','mcv','rdw','plt','log_ferritin'].includes(x.feature)).map(x=>({'变量':variableNames[x.feature]||x.feature,'原始/转换值':x.raw,'训练折均值':x.mean,'训练折标准差':x.sd,'Z分数':x.z}));const methods=preview.processing_catalog.map(x=>({'处理目的':x.purpose,'适用场景':x.when,'常见方法':x.common,'本课实际使用':x.used}));const ferritin=preview.ferritin_transform,summary=[{'分布':'原始铁蛋白',...ferritin.raw.summary},{'分布':'log(1+铁蛋白)',...ferritin.log.summary}].map(x=>({'分布':x['分布'],'偏度':x.skewness,'最小值':x.min,'下四分位数':x.q1,'中位数':x.median,'上四分位数':x.q3,'最大值':x.max}));const compare=ferritin.model_comparison.map(x=>({'逻辑回归输入':x.label,'五折ROC AUC':x.roc_auc,'对数损失（越低越好）':x.log_loss,'铁蛋白系数折间标准差':x.coefficient_sd}));el.innerHTML=`<div class="eyebrow">06 特征工程</div><h1 class="title">先判断数据问题，再选择转换方法</h1><div class="card"><h3>日常分析中常见的数据处理</h3><p class="muted">没有一种转换适合所有变量。下表说明“什么时候用、常用什么、本课实际用了什么”。所有需要学习参数的处理只在训练折拟合。</p>${table(methods)}</div><div class="grid g2"><div class="card"><h3>右偏变量实例：血清铁蛋白原始分布</h3>${bars(ferritin.raw.histogram.map(x=>({label:x.from+'–'+x.to,count:x.count})))}<p class="muted">少数极高值把横轴拉长，原始偏度为 <b>${ferritin.raw.summary.skewness}</b>。</p></div><div class="card"><h3>经过 log(1+x) 后</h3>${bars(ferritin.log.histogram.map(x=>({label:x.from+'–'+x.to,count:x.count})),'label','count','green')}<p class="muted">转换后偏度为 <b>${ferritin.log.summary.skewness}</b>，高值被压缩但患者排序没有被颠倒。</p></div></div><div class="grid g2"><div class="card"><h3>转换前后分布摘要</h3>${table(summary)}<p class="warning">${ferritin.note}</p></div><div class="card"><h3>同一逻辑回归：只替换铁蛋白表达方式</h3>${table(compare)}<p class="muted">比较使用同一套患者级5折；AUC衡量排序，对数损失衡量概率是否合适，系数标准差反映不同折之间是否稳定。</p></div></div><div class="grid g2"><div class="card"><h3>非数值变量怎样进入模型</h3>${table(preview.sex_mapping)}<p class="muted">性别映射成0/1；多个入院诊断则各自展开为0/1列。两者含义不同，不能混为连续测量值。</p>${table(preview.admission_encoding.rows.slice(0,4))}</div><div class="card"><h3>Z标准化：明确是 StandardScaler</h3><p class="muted">公式：z=(当前值−训练折均值)/训练折标准差。逻辑回归与LASSO使用；树和随机森林无需依赖量纲。</p>${table(zrows)}</div></div><button class="button" onclick="go(6)">进入相关性与LASSO筛选</button>`;open=Math.max(open,6);nav()}
async function select(el){preview=preview||await api('/features/preview');const result=selection?`<div class="card"><h3>2. 高相关变量怎样处理</h3>${selection.correlation_filter?.length?table(selection.correlation_filter.map(x=>({'保留变量':x.kept,'剔除变量':x.removed,'实际相关系数':x.correlation,'为什么剔除':x.reason}))):'<p class="good">完整开发数据中未发现 |r|≥0.85 的变量对；每个训练折仍会重新检查。</p>'}</div><div class="grid g2"><div class="card"><h3>3. LASSO系数路径</h3>${lassoPathChart(selection.coefficient_path,selection.lambda_sequence)}<p class="muted">每条线是一项标准化特征。λ越大，惩罚越强，弱特征的系数逐渐归零。</p></div><div class="card"><h3>4. 五折交叉验证选择λ</h3>${lassoCvChart(selection.cv_curve,selection.lambda_min,selection.lambda_1se)}<p class="muted">λmin误差最低；λ1se在误差仍处于“最低值+1个标准误”范围内选择更强惩罚。</p></div></div><div class="grid g2"><div class="card"><h3>5. 1-SE规则最终入选特征</h3>${coefficientBars(selection.selected_coefficients)}<p class="warning">λmin=${Number(selection.lambda_min).toPrecision(3)} 保留 ${selection.selected_min.length} 项；λ1se=${Number(selection.lambda_1se).toPrecision(3)} 保留 ${selection.selected_1se.length} 项。${selection.message}</p></div><div class="card"><h3>未入选变量</h3><div class="tag-cloud">${selection.excluded_features.map(x=>`<span>${esc(x)}</span>`).join('')}</div><h3>嵌套患者级交叉验证</h3>${table(selection.folds.map(x=>({'外层折':x.fold,'训练患者':x.train_patients,'验证患者':x.validation_patients,'患者重叠':x.patient_overlap,'内层选出的λ1se':x.lambda_1se,'入选数':x.selected_count,'外层AUC':x.validation_auc})))}<p class="muted">外层5折评价泛化；每个外层训练集内部再分5折选择λ。验证患者从未参与填补、相关性判断、标准化或选λ。</p></div></div><div class="card"><h3>不同外层训练折中的入选稳定性</h3>${bars(selection.frequency,'feature','folds','orange')}<button class="button" onclick="go(7)">用完整特征与筛选特征分别建模</button></div>`:`<div class="card"><h3>2–5. 运行标准LASSO流程</h3><p>系统将真实计算45个λ：先画系数路径，再用五折交叉验证画误差曲线，并按1-SE规则得到最终特征。</p><p class="muted">为避免“用同一批数据既挑特征又报告成绩”，外层5折负责评价，内层5折只负责选择λ。</p><button class="button" id="run">运行相关性预筛与标准LASSO</button><div id="job"></div></div>`;el.innerHTML=`<div class="eyebrow">07 特征筛选</div><h1 class="title">先去掉重复信息，再让LASSO收缩系数</h1><div class="card"><h3>1. 连续变量相关性热图</h3>${correlationHeatmap(preview.correlation.features,preview.correlation.matrix)}<p class="muted">红框表示 |r|≥0.85。课堂热图使用全部开发数据作描述；真正筛选时，每个训练折独立重算，验证患者不参与。</p></div>${result}`;if(!selection)q('#run').onclick=()=>{q('#run').disabled=true;start('/models/feature-selection/start',q('#job'),'selection')}}
async function selectV2(el){
  preview=preview||await api('/features/preview');
  const workflow=`<div class="card"><h3>本章只做三件事</h3><div class="selection-flow"><span><b>① 相关性去冗余</b><small>先去掉表达重复的信息</small></span><i>→</i><span><b>② LASSO选择λ</b><small>五折交叉验证决定惩罚强度</small></span><i>→</i><span><b>③ 得到最终特征</b><small>进入下一章比较模型</small></span></div><p class="muted">本页最后得到一套课堂展示用特征。下一章评价模型时，相关性处理和LASSO会在每个训练折内重新执行，验证患者不会参与筛选。</p></div>`;
  if(!selection){
    el.innerHTML=`<div class="eyebrow">07 特征筛选</div><h1 class="title">先去掉重复信息，再保留有预测价值的变量</h1>${workflow}<div class="card"><h3>连续变量相关性热图</h3>${correlationHeatmap(preview.correlation.features,preview.correlation.matrix)}<p class="muted">红框表示 |r|≥0.85。这里先观察哪些指标表达了高度重复的信息。</p></div><div class="card"><h3>运行相关性处理与LASSO</h3><p>系统将计算45个λ，绘制系数路径和五折交叉验证曲线，再按1-SE规则形成最终特征表。</p><button class="button" id="run">开始特征筛选</button><div id="job"></div></div>`;
    q('#run').onclick=()=>{q('#run').disabled=true;start('/models/feature-selection/start',q('#job'),'selection')};return;
  }
  const corr=selection.correlation_filter?.length?table(selection.correlation_filter.map(x=>({'保留变量':x.kept,'剔除变量':x.removed,'相关系数 r':x.correlation,'处理理由':x.reason}))):'<p class="good">未发现 |r|≥0.85 的连续变量对。</p>';
  const excluded=selection.excluded_features.map(x=>`<span>${esc(x)}</span>`).join('');
  const chosenLabel=selection.recommended_lambda==='lambda_1se'?'λ1se':'λmin';
  el.innerHTML=`<div class="eyebrow">07 特征筛选</div><h1 class="title">先去掉重复信息，再保留有预测价值的变量</h1>${workflow}<div class="card"><h3>连续变量相关性热图</h3>${correlationHeatmap(preview.correlation.features,preview.correlation.matrix)}<p class="muted">课堂热图描述全部开发数据；模型评价时，每个训练折都会独立重算相关性。</p></div><div class="card"><h3>高度相关变量的处理结果</h3>${corr}</div><div class="grid g2"><div class="card"><h3>LASSO系数路径</h3>${lassoPathChart(selection.coefficient_path,selection.lambda_sequence)}<p class="muted">横轴是log(λ)，纵轴是标准化系数。向右惩罚增强，部分系数逐渐收缩为0。</p></div><div class="card"><h3>五折交叉验证选择λ</h3>${lassoCvChart(selection.cv_curve,selection.lambda_min,selection.lambda_1se)}<p class="muted">λmin给出最低平均偏差；λ1se更精简。系统再用外层验证比较两者，若λ1se损失超过0.01 AUC，就采用λmin，避免过度筛选。</p></div></div><div class="card"><h3>最终进入LASSO模型的特征</h3><div class="grid g2"><div><h4>${chosenLabel} 保留的特征与系数</h4>${coefficientBars(selection.selected_coefficients)}</div><div><h4>没有进入最终特征集</h4><div class="tag-cloud">${excluded}</div><p class="warning">λmin=${Number(selection.lambda_min).toPrecision(3)}，保留 ${selection.selected_min.length} 项；λ1se=${Number(selection.lambda_1se).toPrecision(3)}，保留 ${selection.selected_1se.length} 项。当前采用 <b>${chosenLabel}</b>：${selection.message}</p></div></div><details><summary>查看不同训练折中的入选稳定性</summary><p class="muted">数字表示某特征在5个外层训练折中被选中几次。它用于检查结果是否稳定，不是再次筛选。</p>${bars(selection.frequency,'feature','folds','orange')}</details><button class="button" onclick="go(7)">进入模型比较</button></div>`;
}

function models(el){if(!selection){go(6);return}if(!comparison){el.innerHTML=`<div class="eyebrow">08 模型比较</div><h1 class="title">先验证筛选有没有用，再比较不同模型</h1><div class="grid g3"><div class="card"><h3>逻辑回归与LASSO</h3><p class="muted">普通逻辑回归使用全部变量；LASSO同时收缩系数并筛除变量，直接检验筛选价值。</p></div><div class="card"><h3>决策树与随机森林</h3><p class="muted">保留树模型用于观察非线性关系与过拟合；不把线性LASSO结果机械套给树模型。</p></div><div class="card"><h3>RBF支持向量机</h3><p class="muted">标准化后学习非线性边界；C与gamma只在每个外层训练折内部用4折交叉验证选择。</p></div></div><div class="card"><h3>本章的患者级 5 折方法</h3><p>先把患者固定分成5组。每轮用4组训练、剩余1组验证，轮换5次；五种方案复用完全相同的5次划分。</p><p class="muted">LASSO的λ和SVM参数都只在训练患者内部选择；外层验证患者不参与任何调参。</p><button class="button" id="run">运行五组模型</button><div id="job"></div></div>`;q('#run').onclick=()=>{q('#run').disabled=true;start('/models/compare/start',q('#job'),'comparison')};return}const best=comparison.models.find(x=>x.label===comparison.winner.model&&x.feature_set===comparison.winner.feature_set)||comparison.models[0];const treeRows=comparison.models.filter(x=>x.key==='tree'),maxGap=Math.max(...treeRows.map(x=>x.generalization_gap)),effect=comparison.selection_effect,svm=comparison.models.find(x=>x.key==='svm');const effectText=`LASSO相对普通逻辑回归：验证AUC ${effect.auc_change>=0?'+':''}${effect.auc_change.toFixed(4)}，泛化差距 ${effect.gap_change>=0?'+':''}${effect.gap_change.toFixed(4)}。`;el.innerHTML=`<div class="eyebrow">08 模型比较与过拟合</div><h1 class="title">验证成绩决定泛化能力，训练高分不能单独作结论</h1>${cvPanel(best.folds,'五种方案共同使用的实际五折划分')}<div class="card"><h3>LASSO筛选是否真正改善泛化？</h3><div class="selection-verdict ${effect.improved_auc&&effect.reduced_gap?'good':'warning'}"><b>${effect.improved_auc&&effect.reduced_gap?'本次筛选有效':'本次筛选未同时达到两项目标'}</b><span>${effectText}</span></div><p class="muted">筛选成功不能只看变量变少；至少要同时观察独立验证AUC、训练—验证差距和折间波动。</p></div><div class="grid g2"><div class="card"><h3>五种方案：五折 ROC AUC</h3>${bars(comparison.models.map(x=>({label:x.label+' · '+x.feature_set,score:x.metrics.roc_auc})),'label','score','green')}</div><div class="card"><h3>ROC 曲线</h3>${rocChart(comparison.models)}</div></div><div class="grid g2"><div class="card"><h3>训练 AUC 与验证 AUC 的差距</h3>${gapChart(comparison.models)}<p class="muted">差距越大，说明模型更可能记住训练数据。单棵决策树仅作为过拟合对照。</p></div><div class="card"><h3>最佳模型的混淆矩阵</h3>${confusion(best)}<p class="muted">漏报是“实际地贫但模型未提示”；误报是“实际非地贫但模型提示”。</p></div></div><p class="warning">SVM验证AUC为 ${svm?.metrics.roc_auc}，低于当前推荐模型，且泛化差距达到 ${svm?.generalization_gap}；这说明更复杂的非线性边界在本数据上没有带来更可靠的验证表现。当前推荐：${comparison.winner.model} · ${comparison.winner.feature_set}，五折 AUC ${comparison.winner.auc}。${comparison.winner.rule} 决策树训练—验证差距为 ${maxGap.toFixed(3)}。</p><button class="button" onclick="go(8)">查看 SHAP 解释</button>`}
function modelsV2(el){
  if(!selection){go(6);return}
  if(!comparison){
    el.innerHTML=`<div class="eyebrow">08 模型比较</div><h1 class="title">每种模型都比较全部特征与LASSO筛选后</h1><div class="grid g3"><div class="card"><h3>逻辑回归</h3><p class="muted">比较普通逻辑回归与LASSO逻辑回归，观察变量收缩是否提高泛化。</p></div><div class="card"><h3>决策树与随机森林</h3><p class="muted">分别用全部特征和LASSO筛选后的特征训练，检验线性筛选能否迁移到树模型。</p></div><div class="card"><h3>RBF支持向量机</h3><p class="muted">两套特征分别调节C与gamma，参数只在当前外层训练患者内部选择。</p></div></div><div class="card"><h3>八种方案怎样公平比较</h3><p>固定同一套患者级5折。每轮用4组患者训练、剩余1组验证；需要LASSO的方案只在本轮训练患者中完成相关性处理、标准化和特征筛选。</p><p class="muted">因此验证患者既不参与筛选，也不参与SVM调参。筛选后表现可能提高，也可能下降，两种结果都有教学意义。</p><button class="button" id="run">运行八组模型</button><div id="job"></div></div>`;
    q('#run').onclick=()=>{q('#run').disabled=true;start('/models/compare/start',q('#job'),'comparison')};return
  }
  const best=comparison.models.find(x=>x.label===comparison.winner.model&&x.feature_set===comparison.winner.feature_set)||comparison.models[0];
  const effectRows=comparison.pairwise_effects.map(x=>({'模型':x.model,'全部特征AUC':x.full_auc,'LASSO后AUC':x.selected_auc,'AUC变化':`${x.auc_change>=0?'+':''}${x.auc_change.toFixed(4)}`,'全部特征差距':x.full_gap,'LASSO后差距':x.selected_gap,'差距变化':`${x.gap_change>=0?'+':''}${x.gap_change.toFixed(4)}`}));
  const treeRows=comparison.models.filter(x=>x.key==='tree'),maxGap=Math.max(...treeRows.map(x=>x.generalization_gap));
  el.innerHTML=`<div class="eyebrow">08 模型比较与过拟合</div><h1 class="title">LASSO筛选是否有效，要在每种模型上分别验证</h1>${cvPanel(best.folds,'所有模型共用同一组患者划分')}<div class="card"><h3>筛选前后成对比较</h3>${table(effectRows)}<p class="muted">AUC变化为正表示筛选后排序能力提高；训练—验证差距变化为负表示过拟合减轻。LASSO偏向线性信号，所以不保证每一种非线性模型都会受益。</p></div><div class="grid g2"><div class="card"><h3>八种方案：五折 ROC AUC</h3>${bars(comparison.models.map(x=>({label:x.label+' · '+x.feature_set,score:x.metrics.roc_auc})),'label','score','green')}</div><div class="card"><h3>八条 ROC 曲线</h3>${rocChart(comparison.models)}</div></div><div class="grid g2"><div class="card"><h3>训练 AUC 与验证 AUC 的差距</h3>${gapChart(comparison.models)}<p class="muted">比较同一种算法的两行，才能判断LASSO是否减少过拟合。未剪枝决策树仍作为高方差对照。</p></div><div class="card"><h3>推荐模型的混淆矩阵</h3>${confusion(best)}<p class="muted">漏报是“实际地贫但模型未提示”；误报是“实际非地贫但模型提示”。</p></div></div><p class="warning">当前推荐：${comparison.winner.model} · ${comparison.winner.feature_set}，五折AUC ${comparison.winner.auc}。${comparison.winner.rule} 未剪枝决策树各方案中的最大训练—验证差距为 ${maxGap.toFixed(3)}。</p><button class="button" onclick="go(8)">查看 SHAP 解释</button>`
}

async function shap(el){if(!comparison){go(7);return}const d=await api('/models/explanation/global');el.innerHTML=`<div class="eyebrow">09 模型解释</div><h1 class="title">用 SHAP 图看模型为什么这样判断</h1><div class="grid g2"><div class="card"><h3>全局重要性图</h3>${bars(d.global.slice(0,12),'feature','mean_abs','green')}<p class="muted">平均绝对 SHAP 值越大，模型总体越依赖该特征。</p></div><div class="card"><h3>SHAP 蜂群图</h3>${shapBeeswarm(d.beeswarm)}<p class="muted">每个点是一名患者。横向位置表示推高或压低模型风险，颜色表示该特征的取值高低。</p></div></div><div class="card"><h3>单患者 SHAP 瀑布图</h3><label>选择模拟患者 <select id="patient">${d.patient_options.slice(0,80).map(p=>`<option value="${p.patient_id}">${p.record_id} · 风险 ${p.probability}</option>`).join('')}</select></label><div id="patient-detail"></div></div><div class="card"><h3>风险阈值不是固定答案</h3><p class="muted">降低阈值会提示更多患者，通常减少漏报但增加误报。</p><input id="threshold" type="range" min=".1" max=".9" step=".05" value=".5"><b id="threshold-label">0.50</b><div id="threshold-result"></div></div><p class="warning">SHAP解释的是“模型为何这样输出”，不是地中海贫血的发病机制或因果证据。</p><button class="button" onclick="go(9)">PCA 与无监督探索</button>`;const drawPatient=async()=>{const x=await api('/models/explanation/patient',{method:'POST',body:JSON.stringify({patient_id:q('#patient').value})});q('#patient-detail').innerHTML=`${shapWaterfall(x.contributions,x.base_value,x.probability)}<details><summary>查看转换后数值与精确贡献</summary>${table(x.contributions.slice(0,10).map(z=>({'特征':z.feature,'转换后数值':z.value,'SHAP贡献':z.shap,'方向':z.shap>0?'推高风险':'压低风险'})))}</details>`};const drawThreshold=async()=>{const v=Number(q('#threshold').value);q('#threshold-label').textContent=v.toFixed(2);const x=await api('/models/threshold',{method:'POST',body:JSON.stringify({threshold:v})});q('#threshold-result').innerHTML=`<p>敏感度 <b>${x.metrics.sensitivity}</b>　特异度 <b>${x.metrics.specificity}</b>　漏报 <b>${x.confusion.fn}</b>　误报 <b>${x.confusion.fp}</b></p>`};q('#patient').onchange=drawPatient;q('#threshold').oninput=drawThreshold;drawPatient();drawThreshold();open=Math.max(open,9);nav()}
async function cluster(el){const d=await api('/models/unsupervised/run',{method:'POST'});const profiles=d.after_reveal.map(x=>({'簇编号':x.cluster,'患者数':x.size,'地中海贫血比例':(x.thalassemia_rate*100).toFixed(1)+'%'}));const best=d.comparison.find(x=>x.k===d.recommended_k);el.innerHTML=`<div class="eyebrow">10 无监督探索</div><h1 class="title">不知道答案时，患者会不会自然形成相似人群？</h1><div class="grid g3"><div class="card"><h3>第一步：标准化</h3><p class="muted">KMeans依赖距离，所以连续检验指标先做Z标准化。</p></div><div class="card"><h3>第二步：比较 k=2–5</h3><p class="muted">轮廓系数越高，表示簇内更相似、簇间更分离；惯性用于观察肘部。</p></div><div class="card"><h3>第三步：PCA画图</h3><p class="muted">PCA只把高维结果投影到二维，便于观察，不参与决定疾病诊断。</p></div></div><div class="grid g2"><div class="card"><h3>PCA 二维投影（颜色为聚类结果）</h3>${scatter(d.points,'cluster')}<p class="muted">前两个主成分解释方差：${d.variance.map(x=>(x*100).toFixed(1)+'%').join('、')}。二维图只保留了部分信息。</p></div><div class="card"><h3>簇数比较</h3>${table(d.comparison.map(x=>({'簇数 k':x.k,'轮廓系数':x.silhouette,'簇内距离总和（惯性）':x.inertia})))}<p class="warning">k=${d.recommended_k} 的轮廓系数最高，但最高值只有 ${best.silhouette}，说明自然分群并不强。不能据此把两个簇直接叫作“地贫/非地贫”。</p><h3>最后才揭示出院金标准</h3>${table(profiles)}</div></div>`}
async function clusterV2(el){
  const d=await api('/models/unsupervised/run',{method:'POST'}),best=d.comparison.find(x=>x.k===d.recommended_k),profiles=d.after_reveal.map(x=>({'簇编号':`簇 ${Number(x.cluster)+1}`,'患者数':x.size,'地中海贫血比例':(x.thalassemia_rate*100).toFixed(1)+'%'})),loadingRows=d.loadings.map(x=>({'变量':variableNames[x.feature]||x.feature,'PC1载荷':x.pc1,'PC2载荷':x.pc2}));
  el.innerHTML=`<div class="eyebrow">10 无监督探索</div><h1 class="title">隐藏诊断后，患者会不会自然形成相似人群？</h1><div class="card"><h3>分析顺序</h3><div class="selection-flow"><span><b>① Z标准化</b><small>让不同量纲可以比较距离</small></span><i>→</i><span><b>② PCA二维观察</b><small>只负责投影展示</small></span><i>→</i><span><b>③ 比较k=2–5</b><small>轮廓系数与肘部共同判断</small></span></div></div><div class="card"><h3>PCA二维投影</h3>${scatter(d.points,'cluster')}<p class="muted">PC1和PC2分别解释 ${(d.variance[0]*100).toFixed(1)}% 与 ${(d.variance[1]*100).toFixed(1)}% 的总体变异。点靠近仅表示在这两个主成分上相似，不代表临床诊断相同。</p><details><summary>查看哪些变量构成PC1和PC2</summary>${table(loadingRows)}</details></div><div class="grid g2"><div class="card"><h3>肘部曲线：簇内距离总和</h3>${metricLineChart(d.comparison,'inertia','簇数 k','簇内距离总和（惯性）','#2475c7')}<p class="muted">k增加时惯性必然下降；观察下降幅度从哪里开始明显变缓，而不是只选数值最小处。</p></div><div class="card"><h3>轮廓系数：分组是否清楚</h3>${metricLineChart(d.comparison,'silhouette','簇数 k','轮廓系数','#e87528')}<p class="muted">轮廓系数越高，说明簇内更紧、簇间更分离。本数据实际推荐k=${d.recommended_k}，最高值为 ${best.silhouette}。</p></div></div><div class="card"><h3>聚类完成后再对照出院金标准</h3>${table(profiles)}<p class="warning">PCA负责把高维数据投影到二维；轮廓系数和肘部曲线用于辅助选择k。即使k=2表现较好，也不能把两个簇直接命名为“地贫”和“非地贫”。</p></div>`;
}

q('#reset').onclick=async()=>{await api('/session/reset',{method:'POST'});location.reload()};(async()=>{session=await api('/session/reset',{method:'POST'});render()})();
